export const CRITTER_MOVES = {"bird": {"move": "hops"}, "cat": {"move": "tail flicks"}, "dragon": {"move": "wings lift"}, "owl": {"move": "eyes slide"}};

export function critterSvg(name, frame, px, cls) {
  const body = (CRITTERS[name] || CRITTERS.dragon)[frame || "idle"];
  return '<svg viewBox="0 0 22 22" width="' + (px || 22) + '" height="' +
    (px || 22) + '" class="' + (cls || "") +
    '" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg">' +
    body + '</svg>';
}
